<?php defined('BASEPATH') or exit('No direct script access allowed'); $request=$workspace['request']; $requestId=(int)$request['id']; $requestLines=CompanyPurchasesValues::decode($request['lines_json']); ?>
<section class="purchase-section" data-request-id="<?= $requestId ?>"><h2><?= $e($request['reference'].' · '.$request['title']) ?></h2><p>Necessidade em <?= $e($request['needed_date']) ?> · <?= $e($request['currency']) ?> · <strong><?= $e($states[$request['state']]??$request['state']) ?></strong></p><div class="table-responsive"><table class="purchase-table"><thead><tr><th>Item</th><th>Descrição</th><th>Unidade</th><th>Quantidade</th></tr></thead><tbody><?php foreach ($requestLines as $line) { ?><tr><td><?= (int)$line['line'] ?></td><td><?= $e($line['description']) ?></td><td><?= $e($line['unit']) ?></td><td><?= CompanyPurchasesValues::display($line['quantity_milli'],3) ?></td></tr><?php } ?></tbody></table></div>
