<?php if ($capabilities['create']&&in_array($request['state'],['open','approved'],true)) { ?><details><summary>Registrar cotação recebida fora do portal</summary><p>Os preços seguem a ordem dos itens. Registre uma única taxa percentual para este documento. Vários tributos por item permanecem no fluxo legado até sua adaptação específica.</p><?php $form('quote',null,null,$requestId); ?><input type="hidden" name="purchase[request_id]" value="<?= $requestId ?>"><div class="purchase-grid"><label>Código do fornecedor<input type="number" class="form-control" name="purchase[supplier_id]" min="1" required></label><label>Validade<input class="form-control" type="date" name="purchase[valid_until]" value="<?= gmdate('Y-m-d',time()+7*86400) ?>" min="<?= gmdate('Y-m-d') ?>" required></label><label>Tributo percentual<input class="form-control" name="purchase[tax_rate]" value="0.00" inputmode="decimal" required></label></div><p><a href="<?= $e($url('?tab=suppliers')) ?>">Consultar códigos ou cadastrar fornecedor</a></p><div class="table-responsive"><table class="purchase-table"><thead><tr><th>Item</th><th>Quantidade</th><th>Preço unitário</th></tr></thead><tbody><?php foreach ($requestLines as $line) { ?><tr><td><?= $e($line['description']) ?></td><td><?= CompanyPurchasesValues::display($line['quantity_milli'],3) ?></td><td><input name="purchase[unit_prices][]" inputmode="decimal" required aria-label="Preço <?= $e($line['description']) ?>"></td></tr><?php } ?></tbody></table></div><label>Observações<textarea class="form-control" name="purchase[note]" maxlength="2000"></textarea></label><button>Registrar cotação</button></form></details><?php } ?>
<?php foreach ($workspace['orders'] as $order) { ?><section class="purchase-section"><h3><?= $e($order['reference']) ?> · <?= $e($states[$order['state']]??$order['state']) ?></h3><p>Emissão <?= $e($order['order_date']) ?> · Entrega prevista <?= $e($order['expected_date']) ?> · Total estimado <?= $e($order['currency'].' '.$money($order['total_cents'])) ?></p><p><a href="<?= $e($url('?order_pdf='.(int)$order['id'])) ?>">Baixar pedido PDF</a></p><p class="purchase-note">O pedido conserva a identidade e o preço escolhidos. O tributo é arredondado uma vez por documento fechado; a soma dos tributos de documentos parciais pode diferir alguns centavos da estimativa do pedido.</p>
<?php if ($capabilities['receive']&&in_array($order['state'],['ordered','part_received'],true)) { ?><h4>Registrar recebimento físico</h4><p>Informe somente quantidades recebidas agora. Deixe em branco os itens que ainda não chegaram. O recebimento não atualiza estoque de módulos legados.</p><?php $form('receive',$order['id'],$order['revision'],$requestId); ?><label>Data do recebimento<input class="form-control" type="date" name="purchase[received_date]" value="<?= gmdate('Y-m-d') ?>" max="<?= gmdate('Y-m-d') ?>" min="<?= $e($order['order_date']) ?>" required></label><div class="table-responsive"><table class="purchase-table"><thead><tr><th>Item</th><th>Pedido</th><th>Já recebido</th><th>Recebido agora</th></tr></thead><tbody><?php foreach ($order['receiving']['lines'] as $n=>$line) { $left=$line['quantity_milli']-$order['receiving']['quantities'][$line['line']]; ?><tr><td><?= $e($line['description']) ?></td><td><?= CompanyPurchasesValues::display($line['quantity_milli'],3) ?></td><td><?= CompanyPurchasesValues::display($order['receiving']['quantities'][$line['line']],3) ?></td><td><?php if ($left>0) { ?><input type="hidden" name="purchase[lines][<?= $n ?>][line]" value="<?= (int)$line['line'] ?>"><input name="purchase[lines][<?= $n ?>][quantity]" inputmode="decimal" placeholder="<?= CompanyPurchasesValues::display($left,3) ?>" aria-label="Recebido <?= $e($line['description']) ?>"><?php } ?></td></tr><?php } ?></tbody></table></div><label>Observações<textarea class="form-control" name="purchase[note]" maxlength="2000"></textarea></label><button>Confirmar recebimento parcial ou final</button></form><?php } ?>
<?php if ($capabilities['approve']&&$order['state']==='ordered') { ?><details><summary>Cancelar pedido antes de receber</summary><?php $form('cancel_order',$order['id'],$order['revision'],$requestId); ?><button>Cancelar pedido sem recebimentos</button></form></details><?php } ?>
<h4>Recebimentos e documento do fornecedor</h4><div class="table-responsive"><table class="purchase-table"><thead><tr><th>Recebimento</th><th>Data</th><th>Base atribuída</th><th>Documento</th></tr></thead><tbody><?php foreach ($workspace['receipts'] as $r) { if ((int)$r['order_id']!==(int)$order['id']) { continue; } ?><tr><td><?= $e($r['reference']) ?></td><td><?= $e($r['received_date']) ?></td><td><?= $money($r['base_cents']) ?></td><td><?= $r['document_id']===null?'Ainda não faturado':'Documento #'.$r['document_id'] ?></td></tr><?php } ?></tbody></table></div>
<?php $available=array_values(array_filter($workspace['receipts'],static fn($r)=>(int)$r['order_id']===(int)$order['id']&&$r['document_id']===null)); if ($capabilities['approve']&&$available) { ?><h4>Fechar documento e reconhecer obrigação</h4><p>Selecione os recebimentos deste documento. O fechamento cria uma despesa canônica e um título a pagar. Seus dados e anexos de evidência ficam preservados; recebimentos posteriores devem ser incluídos em outro documento.</p>
<?php if (!$categories) { ?><p class="purchase-warning">Você precisa de uma categoria de despesa ativa e de permissão para criar despesas. <a href="<?= $e(CompanyRequestScope::adminUrl($this,'company_expenses')) ?>">Abrir despesas e categorias</a></p><?php } else { $form('document',null,null,$requestId); ?><input type="hidden" name="purchase[order_id]" value="<?= (int)$order['id'] ?>"><fieldset><legend>Recebimentos ainda não faturados</legend><?php foreach ($available as $r) { ?><label><input type="checkbox" name="purchase[receipt_ids][]" value="<?= (int)$r['id'] ?>"> <?= $e($r['reference'].' · '.$r['received_date'].' · '.$money($r['base_cents'])) ?></label><?php } ?></fieldset><div class="purchase-grid"><label>Número do documento do fornecedor<input class="form-control" name="purchase[vendor_number]" maxlength="100" required></label><label>Data do documento<input class="form-control" type="date" name="purchase[document_date]" value="<?= gmdate('Y-m-d') ?>" max="<?= gmdate('Y-m-d') ?>" required></label><label>Vencimento<input class="form-control" type="date" name="purchase[due_date]" value="<?= gmdate('Y-m-d') ?>" required></label><label>Categoria da despesa<select class="form-control" name="purchase[category_id]" required><?php foreach ($categories as $category) { if (!(int)$category['active']) { continue; } ?><option value="<?= (int)$category['id'] ?>"><?= $e($category['name']) ?></option><?php } ?></select></label></div><label>Anexo do documento<select class="form-control" name="purchase[file_id]"><option value="">Sem arquivo adicional</option><?php foreach ($files as $file) { if ($file['supplier_id']!==null&&(int)$file['supplier_id']!==(int)$order['supplier_id']) { continue; } ?><option value="<?= (int)$file['id'] ?>"><?= $e($file['filename']) ?></option><?php } ?></select></label><button>Fechar documento, despesa e título a pagar</button></form><?php } ?><?php } ?></section><?php } ?>
<?php if ($workspace['payables']) { ?><h3>Títulos deste pedido</h3><p class="purchase-note">O registro de custo e a declaração de quitação são separados. Nenhuma ação desta seção envia instrução bancária ou devolve dinheiro.</p><?php foreach ($workspace['payables'] as $payable) { require APPPATH.'views/admin/companies/purchases_payable.php'; } ?><?php } ?>
<section class="purchase-section"><h3>Anexos privados</h3><p>Somente anexos marcados para o portal aparecem ao fornecedor indicado. Sem fornecedor indicado, a publicação é compartilhada com todos os convites desta requisição. Documentos vinculados a uma obrigação ou quitação são preservados.</p><?php foreach ($files as $file) { ?><p><a href="<?= $e($url('?download='.(int)$file['id'])) ?>"><?= $e($file['filename']) ?></a> · <?= (int)$file['portal_visible']===1?'Publicado no portal':'Privado da equipe' ?><?= $file['supplier_id']===null?'':' · Fornecedor #'.(int)$file['supplier_id'] ?></p><?php if ($capabilities['edit']) { $form('hide_file',$file['id'],$file['revision'],$requestId); ?><button>Ocultar quando não for evidência vinculada</button></form><?php } ?><?php } ?>
<?php if ($capabilities['edit']&&$request['state']!=='cancelled') { $form('upload',null,null,$requestId,true); ?><label>PDF ou imagem<input type="file" name="operation_file" accept="application/pdf,image/png,image/jpeg" required></label><label>Código do fornecedor (opcional)<input type="number" min="1" name="purchase[supplier_id]"></label><input type="hidden" name="purchase[portal_visible]" value="0"><label><input type="checkbox" name="purchase[portal_visible]" value="1"> Publicar este anexo nos convites correspondentes</label><p>Até 20 arquivos e 20 MiB por requisição, incluindo ocultos; PDF até 2 MiB e imagens verificadas e normalizadas.</p><button>Salvar anexo</button></form><?php } ?></section>
<?php if ($capabilities['portal']) { ?><section class="purchase-section"><h3>Convites do fornecedor</h3><p>O convite dá acesso somente a esta requisição e ao fornecedor escolhido. Expira em até 30 dias e pode ser revogado. Copie o link e entregue pelo canal que você escolher; nenhum e-mail é enviado por esta ação.</p>
<?php if ($inviteSecret!==null) { $link=$this->config->site_url('company_purchase_portal').'#invite='.$inviteSecret; ?><p role="status">Convite criado. O segredo só aparece nesta resposta.</p><label>Link do convite<input class="purchase-link form-control" id="purchase-invite-link" readonly value="<?= $e($link) ?>" onclick="this.select()"></label><?php } ?>
<?php if ($request['state']!=='cancelled') { $form('invite',null,null,$requestId); ?><div class="purchase-grid"><label>Código do fornecedor<input type="number" min="1" class="form-control" name="purchase[supplier_id]" required></label><label>Validade em dias<input type="number" min="1" max="30" class="form-control" name="purchase[days]" value="7" required></label></div><button>Criar link de convite</button></form><?php } ?>
<div class="table-responsive"><table class="purchase-table"><thead><tr><th>Fornecedor</th><th>Expiração (UTC)</th><th>Estado</th><th>Ação</th></tr></thead><tbody><?php foreach ($invites as $invite) { ?><tr><td>#<?= (int)$invite['supplier_id'] ?></td><td><?= $e($invite['expires_at']) ?></td><td><?= (int)$invite['revoked']?'Revogado':($invite['expires_at']<=gmdate('Y-m-d H:i:s')?'Expirado':'Ativo') ?></td><td><?php if (!(int)$invite['revoked']) { $form('revoke_invite',$invite['id'],$invite['revision'],$requestId); ?><button>Revogar convite</button></form><?php } ?></td></tr><?php } ?></tbody></table></div></section><?php } ?>
